import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.Dxeykp0S.js";const h=JSON.parse('{"title":"Day 5 · 包管理与现代工程化（uv / pyproject）","description":"","frontmatter":{},"headers":[],"relativePath":"basic/05-packaging.md","filePath":"basic/05-packaging.md","lastUpdated":1787141678000}'),l={name:"basic/05-packaging.md"};function i(d,t,c,n,s,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="day-5-·-包管理与现代工程化-uv-pyproject" tabindex="-1">Day 5 · 包管理与现代工程化（uv / pyproject） <a class="header-anchor" href="#day-5-·-包管理与现代工程化-uv-pyproject" aria-label="Permalink to &quot;Day 5 · 包管理与现代工程化（uv / pyproject）&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>前端工程化你是专家：ESLint、Prettier、Husky、lint-staged。Python 的对应物同样齐全，而且更快——ruff（Rust 写的，对标 ESLint+Prettier 合体）、mypy（对标 tsc）、pre-commit（对标 husky+lint-staged）。今天把工程化体系一次配齐。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>熟练使用 uv 管理依赖与锁定版本</li><li>配置 ruff 做 lint + format</li><li>配置 mypy 做静态类型检查（为进阶班类型提示预热）</li><li>配置 pre-commit 钩子</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://docs.astral.sh/uv/guides/projects/" target="_blank" rel="noreferrer">uv 官方文档：Projects</a></li><li><a href="https://docs.astral.sh/ruff/" target="_blank" rel="noreferrer">ruff 官方文档</a></li><li><a href="https://pre-commit.com/" target="_blank" rel="noreferrer">pre-commit 官方文档</a></li><li>对照速览：</li></ul><table tabindex="0"><thead><tr><th>JS 生态</th><th>Python 生态</th></tr></thead><tbody><tr><td>ESLint + Prettier</td><td>ruff（一个工具全包）</td></tr><tr><td>tsc --noEmit</td><td>mypy</td></tr><tr><td>husky + lint-staged</td><td>pre-commit</td></tr><tr><td>devDependencies</td><td><code>[dependency-groups]</code> dev 组（uv 支持）</td></tr><tr><td>npm run scripts</td><td>无内置，常用 Makefile 或 just</td></tr><tr><td>npm publish</td><td>uv build + uv publish（PyPI）</td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><p><strong>工程化改造</strong>：把入门班 Day 4 的 <code>mytool</code> 项目拿出来，完成：</p><ul><li><code>uv add --dev ruff mypy pytest</code></li><li>在 <code>pyproject.toml</code> 中配置 ruff：行宽 100、启用 <code>E/F/I/UP/B</code> 规则集、开启 import 排序</li><li>运行 <code>uv run ruff check . --fix</code> 和 <code>uv run ruff format .</code>，观察自动修复了什么</li></ul></li><li><p><strong>mypy 严格模式</strong>：配置 <code>pyproject.toml</code> 中 <code>[tool.mypy] strict = true</code>，运行 <code>uv run mypy src/</code>，把报错全部修掉（需要给函数补上类型标注——不熟悉的语法先查，进阶班会系统学）。</p></li><li><p><strong>pre-commit 流水线</strong>：安装 pre-commit，配置 <code>.pre-commit-config.yaml</code>，至少包含 ruff（check + format）和 mypy 三个钩子。故意提交一段有 lint 错误的代码，观察被拦截的过程。</p></li><li><p><strong>发布体验</strong>（可选但推荐）：<code>uv build</code> 打包你的项目，观察 <code>dist/</code> 产物（<code>.whl</code> 和 <code>.tar.gz</code>），了解 twine/uv publish 发布到 PyPI 的流程（不必真发）。</p></li><li><p><strong>依赖审计</strong>：体验 <code>uv tree</code> 查看依赖树（对标 <code>npm ls</code>），<code>uv lock --upgrade</code> 升级依赖，理解 uv.lock 的锁定机制。</p></li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li>ruff 为什么比传统 Python linter（flake8/pylint）快几个数量级？</li><li><code>uv add</code> 和 <code>uv add --dev</code> 的区别在 pyproject.toml 里如何体现？</li><li>mypy 的类型检查发生在什么时候？运行时还有效吗？（对比 TypeScript 的&quot;类型擦除&quot;）</li><li>pre-commit 的钩子是装在哪里的？团队成员如何自动同步？</li><li>Python 的 wheel（.whl）和 sdist（.tar.gz）有什么区别？</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://astral.sh/" target="_blank" rel="noreferrer">Astral 全家桶：uv + ruff + ty</a></li><li><a href="https://cjolowicz.github.io/posts/hypermodern-python-01-setup/" target="_blank" rel="noreferrer">Hypermodern Python 系列文章</a>（经典工程化教程）</li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>基础班通关！下一站<a href="/python-practices/advanced/">进阶班</a>：asyncio、GIL、类型提示、FastAPI、pytest——从&quot;会 Python&quot;到&quot;会用 Python 做工程&quot;。</p>',18)])])}const m=e(l,[["render",i]]);export{h as __pageData,m as default};
